SELECT sd.DEPARTMENT_NAME, AVG(tso.NUM_ENROLLED_STUDENTS) AS avg_enrolled, VARIANCE(tso.NUM_ENROLLED_STUDENTS) AS enrolled_variance, STDDEV(tso.NUM_ENROLLED_STUDENTS) AS enrolled_stddev FROM TIP_SUBJECT_OFFERED tso JOIN SIS_DEPARTMENT sd ON tso.OFFER_DEPT_CODE = sd.DEPARTMENT_CODE JOIN MIT_STUDENT_DIRECTORY msd ON sd.DEPARTMENT_CODE = msd.DEPARTMENT WHERE sd.IS_DEGREE_GRANTING = 'Y' AND msd.STUDENT_YEAR = '4' AND sd.DEPARTMENT_NAME = 'Mathematics' GROUP BY sd.DEPARTMENT_NAME ORDER BY enrolled_variance DESC;